/** Nom d'une langue dans la langue affichée (ex. « Allemand », « German », « Deutsch ») */
export function langName(code, inLang) {
  try { const n = new Intl.DisplayNames([inLang], { type: 'language' }).of(code); return n ? n.charAt(0).toLocaleUpperCase(inLang) + n.slice(1) : code.toUpperCase(); }
  catch { return LANG_NAMES[code] || code.toUpperCase(); }
}

export const RESOURCES = { en, fr, de, it, es };

/** Noms de lieux qui changent selon la langue (la valeur envoyée à l'API reste le nom d'origine) */
const PLACE_NAMES = {
  Tunis: { it: 'Tunisi', es: 'Túnez' }, Sousse: { es: 'Susa' }, Djerba: { es: 'Yerba' }, Sahara: { es: 'Sáhara' },
  Kairouan: { es: 'Kairuán' }, 'Tozeur & Chebika': { it: 'Tozeur e Chebika', es: 'Tozeur y Chebika' },
};
export const placeName = (name, lang) => PLACE_NAMES[name]?.[lang] || name;

i18n.use(initReactI18next).init({
  resources: Object.fromEntries(Object.entries(RESOURCES).map(([l, r]) => [l, { t: r }])),
  ns: ['t'], defaultNS: 't',
  lng: DEFAULT_LANG, fallbackLng: 'en',
  interpolation: { escapeValue: false },
  returnObjects: true,
});

export default i18n;
